insert into plant (plant_id, plant_category, scientific_name, common_name, plant_picture_url, plant_count, water_cycle, light_demand, growth_temperature, humidity, fertilizer, manage_level, other_information, create_date, update_date, plant_picture_url_s3)
values (1,'백합과','Dracaena fragrans var. massangeana','드라세나 맛상게아나','https://nongsaro.go.kr/cms_contents/301/14690_MF_REPR_ATTACH_01.jpg',0,'봄,여름,가을에는 물에 잠기지 않도록 주의하여 흙을 촉촉하게 유지해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','햇빛에 크게 영향을 받지 않아요.','16~20℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.(수용성비료 2주에 한번 줌)','쉬움','드라세나 맛상게아나는(은) 백합과 식물입니다. 높이는 150cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색,기타입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/14690_MF_REPR_ATTACH_01.jpg'),
       (2,'고사리과','Adiantum raddianum','아디안텀','https://nongsaro.go.kr/cms_contents/301/19467_MF_REPR_ATTACH_01.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','적당한 햇빛 또는 강한 햇빛이 필요해요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.','보통','아디안텀는(은) 고사리과 식물입니다. 높이는 40cm까지 자라며, 거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19467_MF_REPR_ATTACH_01.jpg'),
       (3,'백합과','Dracaena sanderiana','드라세나 산데리아나','https://nongsaro.go.kr/cms_contents/301/14691_MF_REPR_ATTACH_01.gif',0,'봄,여름,가을에는 물에 잠기지 않도록 주의하여 흙을 촉촉하게 유지해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','햇빛에 크게 영향을 받지 않아요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.(봄~가을 완효성비료를 규칙적으로 줌)','쉬움','드라세나 산데리아나는(은) 백합과 식물입니다. 높이는 100cm까지 자라며, 실내 어두운 곳,거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색,흰색, 크림색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/14691_MF_REPR_ATTACH_01.jpg'),
       (4,'아라우카리아과','Araucaria heterophylla','아라우카리아','https://nongsaro.go.kr/cms_contents/301/19466_MF_ATTACH_03.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','적당한 햇빛 또는 강한 햇빛이 필요해요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.','쉬움','아라우카리아는(은) 아라우카리아과 식물입니다. 높이는 150cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19466_MF_ATTACH_03.jpg'),
       (5,'천남성과','Aglaonema commutatum','아글라오네마','https://nongsaro.go.kr/cms_contents/301/19469_MF_ATTACH_04.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','햇빛에 크게 영향을 받지 않아요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.','보통','아글라오네마는(은) 천남성과 식물입니다. 높이는 50cm까지 자라며, 실내 어두운 곳,거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색,은색, 회색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19469_MF_ATTACH_04.jpg'),
       (6,'협죽도과','Adenium obesum','아데니움','https://nongsaro.go.kr/cms_contents/301/19468_MF_ATTACH_01.jpg',0,'봄,여름,가을,겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','아주 강한 햇빛이 필요해요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.(2회/년, 4월, 7월)','보통','아데니움는(은) 협죽도과 식물입니다. 높이는 40cm까지 자라며, 거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색이며 분홍색,빨강색,흰색,혼합색의 꽃이 핍니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19468_MF_ATTACH_01.jpg'),
       (7,'백합과','Dracaena reflexa Song of India','드라세나 송오브인디아','https://nongsaro.go.kr/cms_contents/301/14694_MF_ATTACH_02.jpg',0,'봄,여름,가을에는 물에 잠기지 않도록 주의하여 흙을 촉촉하게 유지해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','햇빛에 크게 영향을 받지 않아요.','16~20℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.(봄~가을 완효성비료를 규칙적으로 주고 겨울에 중단)','쉬움','드라세나 송오브인디아는(은) 백합과 식물입니다. 높이는 150cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색,금색, 노란색이며 흰색의 꽃이 핍니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/14694_MF_ATTACH_02.jpg'),
       (8,'고란초과','Asplenium nidus','아스플레니움','https://nongsaro.go.kr/cms_contents/301/19463_MF_REPR_ATTACH_01.jpg',0,'봄,여름,가을에는 흙을 항상 축축하게 물에 잠길 정도로 유지해주세요. 겨울에는 토양 표면이 말랐을때 충분히 관수해주세요. ','적당한 햇빛 또는 강한 햇빛이 필요해요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요. (1회/년, 봄)','보통','아스플레니움는(은) 고란초과 식물입니다. 높이는 40cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19463_MF_REPR_ATTACH_01.jpg'),
       (9,'뽕나무과','Ficus panda ','팬더 고무나무','https://nongsaro.go.kr/cms_contents/301/13242_MF_ATTACH_01.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','적당한 햇빛 또는 강한 햇빛이 필요해요.','21~25℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.','보통','팬더 고무나무는(은) 뽕나무과 식물입니다. 높이는 50cm까지 자라며, 거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색입니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/13242_MF_ATTACH_01.jpg'),
       (10,'백합과','Dracaena surculosa (D. godseffiana)','드라세나 수르쿨로사','https://nongsaro.go.kr/cms_contents/301/14695_MF_REPR_ATTACH_01.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','햇빛에 크게 영향을 받지 않아요.','16~20℃','40%미만의 건조한 환경을 유지해주세요.','비료를 보통 요구해요.(동절기 비료주지 않음)','보통','드라세나 수르쿨로사는(은) 백합과 식물입니다. 높이는 150cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색,흰색, 크림색이며 흰색의 꽃이 핍니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/14695_MF_REPR_ATTACH_01.jpg'),
       (11,'인동과','Viburnum odoratissimum var. awabuki','아왜나무','https://nongsaro.go.kr/cms_contents/301/19462_MF_REPR_ATTACH_01.jpg',0,'봄,여름,가을에는 토양 표면이 말랐을때 충분히 관수해주세요. 겨울에는 화분 흙이 대부분 말랐을때 충분히 관수해주세요. ','적당한 햇빛 또는 강한 햇빛이 필요해요.','16~20℃','40~70%의 적당한 습도를 유지해주세요.','비료를 보통 요구해요.','쉬움','아왜나무는(은) 인동과 식물입니다. 높이는 150cm까지 자라며, 거실 내측,거실 창측,발코니 내측,발코니 창측에서 키우는 것이 가장 적합합니다. 잎은 녹색, 연두색이며 흰색의 꽃이 핍니다.','2025-02-12 00:39:08','2025-02-12 00:51:38','plant/19462_MF_REPR_ATTACH_01.jpg'),
